def page_ranked(post, sort, cursor, limit=20):
  key = f'{sort}:{{{post}}}'
  if cursor is None:
      snap = now(); hi = '+inf'; last_id = None
  else:
      snap, hi, last_id = cursor.ts, cursor.score, cursor.id
  out = []
  while len(out) < limit:
      batch = redis.zrevrangebyscore(key, hi, '-inf', withscores=True,
                                     start=0, num=limit * 2)
      if not batch: break
      for cid, score in batch:
          if (score, cid) >= (hi, last_id) and last_id is not None:
              continue                          # already served (ties)
          if created_at(cid) > snap: continue   # newer than snapshot
          out.append((cid, score))
          if len(out) == limit: break
      hi, last_id = batch[-1][1], batch[-1][0]
  nxt = encode(sort, out[-1][1], out[-1][0], snap) if out else None
  return out, nxt

def wilson_lower(pos, n, z=1.96):
  if n == 0: return 0.0
  p = pos / n
  return (p + z*z/(2*n) - z*math.sqrt((p*(1-p) + z*z/(4*n)) / n)) / (1 + z*z/n)

def best_score(c, now):
  q = wilson_lower(c.likes, c.likes + c.negatives)
  age_h = (now - c.created_at).hours
  decay = 1 / (1 + age_h / 24) ** 0.5               # gentle
  return q * decay + (0.05 if c.author_is_creator else 0)

